import{_ as r,o as n,c as s,a2 as a,j as e,a as t}from"./chunks/framework.l66uSLlc.js";const g=JSON.parse('{"title":"Roadmap","description":"Three horizons for Noto, the gate between each, how releases work, and what Noto will not build.","frontmatter":{"title":"Roadmap","description":"Three horizons for Noto, the gate between each, how releases work, and what Noto will not build."},"headers":[],"relativePath":"direction/roadmap.md","filePath":"direction/roadmap.md","lastUpdated":1792727050000}'),i={name:"direction/roadmap.md"};function l(d,o,h,c,p,u){return n(),s("div",null,[...o[0]||(o[0]=[a(`<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Adopted 2026-09-29</p><p>The owner adopted this roadmap on 2026-09-29; each decision behind it is in the <a href="./decisions#decided">decision log</a>. The first release outside alpha was <code>0.0.3</code>, on 2026-10-17, shipped unsigned under D2 as amended that day.</p></div><p>Three horizons, each ending in a gate rather than a date. Work moves to the next horizon when the gate is met, not when the calendar says so.</p><h2 id="now" tabindex="-1">Now: make it trustworthy <a class="header-anchor" href="#now" aria-label="Permalink to &quot;Now: make it trustworthy {#now}&quot;">​</a></h2><p><strong>Gate:</strong> the first release outside alpha. <a href="./decisions#decided">D2</a> named it <code>0.1.0</code> and required <code>@roobli/md</code> on by default (done in <code>v0.0.2-alpha.112</code>) and the items marked <strong>gate</strong> below. As amended on 2026-10-17, it became <code>0.0.3</code>, shipped that day without signing; the signing items now gate the first signed release instead. The unmarked items may follow in any release.</p><ol><li><strong>Stable means stable.</strong> Gate. Done in <a href="https://github.com/roobli/Noto/pull/289" target="_blank" rel="noreferrer">roobli/Noto#289</a>: the release flags were corrected on GitHub the day it merged, and the updater&#39;s own check ships with the next build. <ul><li>Correct the prerelease flag on every <code>v*-alpha.*</code> release on GitHub.</li><li>Make the updater refuse any version with a semver prerelease component on the Stable channel, whatever GitHub says. This covers both the in-app check and the <code>electron-updater</code> path, which reads GitHub&#39;s &quot;latest release&quot; and is misled the same way.</li><li>Create the GitHub release in the release workflow, with the prerelease flag derived from the tag, so a hand-made release cannot drift again.</li></ul></li><li><strong>Signed and notarized on macOS.</strong> Gate for the first signed release, deferred from <code>0.0.3</code>. The release workflow signs, notarizes and verifies as soon as the credentials exist (<a href="https://github.com/roobli/Noto/pull/291" target="_blank" rel="noreferrer">roobli/Noto#291</a>, with the list in <code>RELEASING.md</code>); what remains is the account and the certificate. <ul><li>Apple Developer Program membership and a Developer ID Application certificate, held by the organization rather than a personal account if possible.</li><li>Notarize with <code>notarytool</code> using an App Store Connect API key, which is revocable and not tied to one person&#39;s Apple ID and two-factor prompts. Staple the ticket. Verify with <code>spctl --assess</code> and a launch from quarantine on a clean machine.</li><li>Entitlements: remove <code>disable-library-validation</code>, then <code>allow-unsigned-executable-memory</code>, one per build, each verified by a notarized launch from quarantine, as the <a href="https://github.com/roobli/Noto/blob/main/docs/architecture/signing-review.md" target="_blank" rel="noreferrer">signing review</a> already prescribes.</li><li>Retire the first-open instructions only after a notarized build passes that check.</li><li>From the first release after 0.0.3, the app installs no update itself on any platform; a found update opens its download. 0.0.3 itself can install one after the reader presses Download (<a href="https://github.com/roobli/Noto/pull/329" target="_blank" rel="noreferrer">roobli/Noto#329</a>).</li></ul></li><li><strong>Signed on Windows.</strong> SmartScreen is the same first-minute problem on the other platform. Signing through the SignPath Foundation&#39;s open-source programme (<a href="./decisions#decided">D15</a>); the application comes first.</li><li><strong>Every Mac.</strong> Gate, met in the release workflow (<a href="./decisions#decided">D8</a>): each release builds an Intel zip beside the Apple silicon one, and the update feed lists both.</li><li><strong>Numbers that are current.</strong> Gate, met. Re-measure open, keystroke and save on packaged builds with <code>@roobli/md</code> as the default, against the same Typora and corpus, and replace the README table. Keep the old table in the measurement record with its date. <ul><li>Noto&#39;s half is done: a <a href="https://github.com/roobli/Noto/blob/main/.github/workflows/bench.yml" target="_blank" rel="noreferrer">benchmark workflow</a> measures a packaged build on every tag, and the README shows its numbers for <code>main</code> on 29 September 2026 (<a href="https://github.com/roobli/Noto/pull/296" target="_blank" rel="noreferrer">roobli/Noto#296</a>).</li><li>Getting there found two problems in long notes, both fixed: a save that grew with the square of the number of blocks (<a href="https://github.com/roobli/Noto/pull/294" target="_blank" rel="noreferrer">roobli/Noto#294</a>), and a spell checker that froze the window for over a minute each time typing paused in the 8 MB test document (<a href="https://github.com/roobli/Noto/pull/295" target="_blank" rel="noreferrer">roobli/Noto#295</a>).</li><li>October&#39;s work on long notes followed from those numbers: fences, tables and display math far from the caret drawn as they scroll into view, runs of off-screen blocks kept as single placeholders, a save that writes out only the blocks that changed, and the document crossing between processes once instead of twice. In the packaged benchmark for <code>v0.0.2-alpha.114</code>, the 8 MB document opens in about a second and a quarter instead of ten, a keystroke takes about 21 ms instead of 86, and a save under half a second instead of about three (<a href="https://github.com/roobli/Noto/blob/main/docs/performance/measurements.md" target="_blank" rel="noreferrer">measurements</a>).</li><li>Still open, and deferred to the first signed release: the comparison with Typora, repeated with the current engine on a Mac that has Typora installed.</li></ul></li><li><strong>An honest front door.</strong> Done: download links and version facts on this site are generated from the Releases API at build time; screenshots are retaken on the current chrome against a synthetic vault, in English and Chinese; the README&#39;s download table matches what releases carry. A macOS retake of the screenshots is still wanted.</li><li><strong>Release notes for people.</strong> Done in <a href="https://github.com/roobli/Noto/pull/291" target="_blank" rel="noreferrer">roobli/Noto#291</a>: a <code>CHANGELOG.md</code> in <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> form, written for the person updating, with engine detail linked to <code>@roobli/md</code>&#39;s own changelog, and a <code>RELEASING.md</code> that turns <a href="./decisions#decided">D4</a> into steps.</li><li><strong>Saves that stay true under the speed work.</strong> Done after <code>0.0.3</code>. The sparse view depends on ProseMirror internals, so <code>prosemirror-view</code> is pinned to <code>1.42.3</code> and its shape is checked at startup, with ordinary rendering if the check fails (<a href="https://github.com/roobli/Noto/pull/330" target="_blank" rel="noreferrer">roobli/Noto#330</a>). A round-trip property test makes random edits to a 3,200-block note on the sparse path and requires each save to parse back to the editor&#39;s document (<a href="https://github.com/roobli/Noto/pull/333" target="_blank" rel="noreferrer">roobli/Noto#333</a>). It found three save bugs, fixed with it. Later fixes close more, each also present in <code>0.0.3</code>: a block edited before it finished loading saved its markup escaped (<a href="https://github.com/roobli/Noto/pull/335" target="_blank" rel="noreferrer">#335</a>); literal stars turned into italics (<a href="https://github.com/roobli/Noto/pull/336" target="_blank" rel="noreferrer">#336</a>); <code>&amp;amp;</code> and its kin saved as <code>\\&amp;amp;</code> (<a href="https://github.com/roobli/Noto/pull/337" target="_blank" rel="noreferrer">#337</a>); two lists merged when the paragraph between them went (<a href="https://github.com/roobli/Noto/pull/339" target="_blank" rel="noreferrer">#339</a>); and nested emphasis, and bold inside italic, saved in a form that reopened differently (<a href="https://github.com/roobli/Noto/pull/340" target="_blank" rel="noreferrer">#340</a>, <a href="https://github.com/roobli/Noto/pull/341" target="_blank" rel="noreferrer">#341</a>). None of these has been released yet.</li></ol><h2 id="next" tabindex="-1">Next: make it Noto&#39;s own <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next: make it Noto&#39;s own {#next}&quot;">​</a></h2><p><strong>Gate:</strong> a release a stranger would recommend to a friend without caveats.</p><ol><li><strong>Defaults for everyone.</strong> Per-script typography, a reviewed set of defaults, the author&#39;s setup kept as a preset (<a href="./principles#_3-defaults-are-the-product">rule 3</a>).</li><li><strong>Accessibility.</strong> VoiceOver and Narrator through open, edit, save, quick open and Settings; keyboard reach for every control; contrast checked in both themes.</li><li><strong>One engine.</strong> Done on 2026-10-17, ahead of <a href="./decisions#decided">D12</a>&#39;s two-release criterion: the <code>NOTO_MARKDOWN_ENGINE=micromark</code> switch and the old markdown pipelines are gone (<a href="https://github.com/roobli/Noto/pull/332" target="_blank" rel="noreferrer">roobli/Noto#332</a>). micromark and mdast remain only where the default engine uses them. Two parsers were two sets of bugs, two golden baselines and a second question on every review.</li><li><strong>Open time.</strong> The last side-by-side measurement, with the previous parser, had Typora 2.6 times faster on a 525 KB file. Close that gap with the new engine, or explain it with new numbers measured on one machine. The 8 MB keystroke, about five frames at the end of September, is now a little over one.</li><li><strong>Settings audit</strong> (<a href="./principles#_6-a-setting-is-a-decision-not-yet-made">rule 6</a>).</li><li><strong>The writing loop</strong>, in the order a writer meets it: paste, undo, input method composition, spell check, find, export. Each checked against <a href="https://github.com/roobli/Noto/blob/main/docs/design/typora-gap.md" target="_blank" rel="noreferrer">the Typora record</a>, and only where it serves writing and reading.</li></ol><h2 id="later" tabindex="-1">Later: open the doors carefully <a class="header-anchor" href="#later" aria-label="Permalink to &quot;Later: open the doors carefully {#later}&quot;">​</a></h2><p><strong>Gate:</strong> none until Next is done. These are directions, not commitments.</p><ol><li><strong>User-installed plugins</strong>, through the isolated runtime that is already built: a plugins folder, a package digest, an install surface and a versioned API. This is when the <a href="https://github.com/roobli/noto-plugin-template" target="_blank" rel="noreferrer">plugin template</a> becomes a product.</li><li><strong><code>@roobli/md</code> on npm</strong> with a v1 contract, so other hosts can share Noto&#39;s fidelity guarantee.</li><li><strong>Noto on the web</strong>, in the <a href="#web">track below</a>.</li><li><strong>Canvas documents</strong>, only if Noto decides to host them and only through the sandbox. Until then <code>@roobli/canvas</code> waits.</li></ol><h2 id="web" tabindex="-1">Noto on the web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Noto on the web {#web}&quot;">​</a></h2><p>Proposed by the owner and adopted as <a href="./decisions#decided">D13</a>, with its gate re-pointed on 2026-10-20 to the first signed release: run Noto&#39;s core in the browser, and build this site with it. The site stops describing Noto and starts being made of it, so every page is evidence for the claim it makes.</p><h3 id="why-it-is-within-reach" tabindex="-1">Why it is within reach <a class="header-anchor" href="#why-it-is-within-reach" aria-label="Permalink to &quot;Why it is within reach&quot;">​</a></h3><p>Measured on <code>v0.0.2-alpha.113</code>:</p><ul><li>The Markdown pipeline (<code>src/shared/markdown/v3</code>) touched Node in one place: a <code>createHash</code> call for a sha256 in <code>document.ts</code>. That is gone since <a href="https://github.com/roobli/Noto/pull/293" target="_blank" rel="noreferrer">roobli/Noto#293</a>.</li><li>The editor (<code>src/renderer/editor/noto</code>, about 11,500 lines) never calls the desktop bridge. It imports ProseMirror, Prism, KaTeX and shared code, and two small renderer helpers.</li><li><code>@roobli/md</code> already runs in the browser on this site.</li><li>What is desktop-only is the file layer in the main process: reading, block records, the save that refuses on conflict, recovery, the workspace and plugins.</li></ul><p>So the work is a boundary, not a rewrite.</p><h3 id="one-core-two-hosts" tabindex="-1">One core, two hosts <a class="header-anchor" href="#one-core-two-hosts" aria-label="Permalink to &quot;One core, two hosts&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>          @roobli/md (MIT)</span></span>
<span class="line"><span>          parse · split · reparse · serialize</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>          Noto core (AGPL)</span></span>
<span class="line"><span>          schema · engine IR → ProseMirror · editor</span></span>
<span class="line"><span>          document styles · byte-exact save assembly</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>      ┌──────────┴────────────┐</span></span>
<span class="line"><span>  Desktop host             Web host</span></span>
<span class="line"><span>  Electron main: files,    fetch: read-only pages</span></span>
<span class="line"><span>  block records,           File System Access:</span></span>
<span class="line"><span>  recovery, workspace,     a local folder</span></span>
<span class="line"><span>  plugins                  GitHub: an edit becomes</span></span>
<span class="line"><span>                           a pull request</span></span></code></pre></div><p>Groundwork, which also helps the desktop app:</p><ol><li><strong>Hashing that runs anywhere.</strong> Done in <a href="https://github.com/roobli/Noto/pull/293" target="_blank" rel="noreferrer">roobli/Noto#293</a>: the shared layer hashes with a synchronous sha256 in plain JavaScript, and the desktop installs Node&#39;s native one, which gives the same digests three to four times faster. Measuring it found a save path that was quadratic in the number of blocks, fixed in <a href="https://github.com/roobli/Noto/pull/294" target="_blank" rel="noreferrer">roobli/Noto#294</a>: the groundwork paid for itself on the desktop first.</li><li><strong>A named host boundary.</strong> What <code>App</code> hands the editor today becomes a <code>NotoHost</code> interface: read bytes, save bytes against a base hash, resolve an asset, resolve a wiki link, open a link. The desktop implements it with the preload APIs it already has.</li><li><strong>A web build of the core</strong> from the Noto repository, a library entry consumed here by tag the way <code>@roobli/md</code> is. No monorepo migration until a second consumer needs one.</li></ol><h3 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;Phases&quot;">​</a></h3>`,23),e("div",{class:"table-scroll",tabindex:"0",role:"region","aria-label":"Table: Phase, What ships, When"},[e("table",null,[e("colgroup",null,[e("col",{style:{width:"6.2%"}}),e("col",{style:{width:"80.4%"}}),e("col",{style:{width:"13.4%"}})]),e("thead",null,[e("tr",null,[e("th",null,"Phase"),e("th",null,"What ships"),e("th",null,"When")])]),e("tbody",null,[e("tr",null,[e("td",null,[e("strong",null,"W0")]),e("td",null,[t("The engine preview on the engine Noto ships, and a check on every pull request and deploy that each page of this site comes back byte for byte from "),e("code",null,"@roobli/md"),t(". The site's own pages become part of the engine's evidence.")]),e("td",null,"Done")]),e("tr",null,[e("td",null,[e("strong",null,"W1")]),e("td",null,"Pages drawn by Noto. This site's Markdown is rendered by the Noto core, with the app's schema, typography and node views, inside VitePress's shell, which stays for navigation and search. Server-render what the schema can for first paint; mount the read-only editor for exact visuals."),e("td",null,"After the first signed release")]),e("tr",null,[e("td",null,[e("strong",null,"W2")]),e("td",null,[t("Edit this page, keep the file. Every page gets "),e("em",null,"Edit in Noto"),t(": the page becomes editable in the browser, and saving assembles the file exactly as the desktop does and opens a pull request. The diff is the edit and nothing else. This is the pitch, demonstrated on every page.")]),e("td",null,"After W1")]),e("tr",null,[e("td",null,[e("strong",null,"W3")]),e("td",null,"Noto for the web: a local folder through the File System Access API, or a public repository read-only. A second product surface, which needs its own case."),e("td",null,"Decided after W2 has been used")])])])],-1),a('<p>The groundwork may run while the gate waits on certificates. Nothing in this track ships ahead of the first signed release (D13 as amended on 2026-10-20; it named <code>0.1.0</code> before <code>0.0.3</code> shipped unsigned), and none of it is a cloud: no accounts, no sync, no hosted notes.</p><h2 id="no" tabindex="-1">Not on the roadmap <a class="header-anchor" href="#no" aria-label="Permalink to &quot;Not on the roadmap {#no}&quot;">​</a></h2><p>Saying no is the other half of a roadmap. These are good ideas that belong to other products.</p><ul><li>Accounts, sync, or a Noto cloud. Files already sync through whatever the reader uses.</li><li>Real-time collaboration.</li><li>Mobile apps.</li><li>A writing assistant inside the editor. What Noto offers people who work with agents is fidelity and the local <a href="./../guide/remote-control">remote control</a> API, not a chat pane.</li><li>Databases, block references and Notion-style pages.</li><li>A full diagrams.net editor inside Noto.</li><li>Deeper nesting for its own sake. Thirty-seven levels of nested emphasis is past anything a person writes. The cap is a decision, not a gap, and no release will exist only to raise it.</li></ul><h2 id="releases" tabindex="-1">How releases work <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;How releases work {#releases}&quot;">​</a></h2>',5),e("div",{class:"table-scroll",tabindex:"0",role:"region","aria-label":"Table: Track, Meaning, Cadence, Update channel"},[e("table",null,[e("colgroup",null,[e("col",{style:{width:"18.0%"}}),e("col",{style:{width:"42.7%"}}),e("col",{style:{width:"23.2%"}}),e("col",{style:{width:"16.1%"}})]),e("thead",null,[e("tr",null,[e("th",null,"Track"),e("th",null,"Meaning"),e("th",null,"Cadence"),e("th",null,"Update channel")])]),e("tbody",null,[e("tr",null,[e("td",null,"CI build"),e("td",null,[t("Every merge to "),e("code",null,"main"),t(", kept as workflow artifacts")]),e("td",null,"Continuous"),e("td",null,"None")]),e("tr",null,[e("td",null,[t("Alpha ("),e("code",null,"…-alpha.n"),t(")")]),e("td",null,"A user-visible change worth testing"),e("td",null,"At most weekly, with notes"),e("td",null,"Testing")]),e("tr",null,[e("td",null,"Release"),e("td",null,"Passed the current horizon's gate"),e("td",null,"Per milestone"),e("td",null,"Stable and Testing")])])])],-1),e("p",null,[t("For context: 113 alphas were tagged between 5 and 28 September 2026, 23 of them in the last three days. At that rate the version number carries no information, and anyone on Testing is asked to update several times a day. A build is not a release. The table keeps the engineering pace and gives the version number its meaning back. Since then the table has held: one alpha, "),e("code",null,"v0.0.2-alpha.114"),t(" on 12 October, then "),e("code",null,"0.0.3"),t(" on 17 October, the first release outside alpha ("),e("a",{href:"./decisions#decided"},"D2, amended"),t(").")],-1)])])}const m=r(i,[["render",l]]);export{g as __pageData,m as default};
